const products=[
{id:'cuban',name:'The Westside Cuban',category:'Chains',price:129,description:'Bold links. An unmistakable silhouette. The anchor of your everyday rotation.'},
{id:'rope',name:'The Sunset Rope',category:'Chains',price:89,description:'A twisted silhouette that catches the light. Wear it solo or build your own layers.'},
{id:'cross',name:'The Crossroads Pendant',category:'Pendants',price:69,description:'A sculptural cross with a sharp, expressive edge. A small piece with a strong presence.'},
{id:'sun',name:'The Sol Pendant',category:'Pendants',price:75,description:'A sun-inspired motif for carrying a little golden-hour energy into the everyday.'},
{id:'signet',name:'The Midnight Signet',category:'Rings',price:59,description:'A dark face framed by a bold silver-tone silhouette. Understated, never unnoticed.'},
{id:'flame',name:'The Wildfire Ring',category:'Rings',price:65,description:'Sculpted flames and flowing lines. Turn the volume up on your ring stack.'},
{id:'bracelet',name:'The Boulevard Bracelet',category:'Bracelets',price:95,description:'Chunky links with an easy attitude. A finishing detail with a little extra weight in style.'},
{id:'cuff',name:'The Pacific Cuff',category:'Bracelets',price:79,description:'An open silhouette with fluid contours. A quieter statement that holds its own.'}
];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const imageStyle=p=>{const i=products.indexOf(p);return `--x:${(i%4)*100/3}%;--y:${i<4?0:100}%`};
const imageHTML=p=>`<div class="product-image" style="${imageStyle(p)}" role="img" aria-label="${p.name}, silver-tone concept design"></div>`;
const storageKey='westside-demo-bag-v1';let bag={};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const p of products){const q=saved[p.id];if(Number.isInteger(q)&&q>0)bag[p.id]=Math.min(q,99)}}catch{}
let toastTimer;function announce(message){const el=document.querySelector('#status');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
function saveBag(){try{localStorage.setItem(storageKey,JSON.stringify(bag))}catch{}document.querySelector('#bag-count').textContent=Object.values(bag).reduce((a,b)=>a+b,0)}
function addToBag(id){if((bag[id]||0)>=99){announce('Maximum 99 of each sample piece.');return}bag[id]=(bag[id]||0)+1;saveBag();announce(`${products.find(p=>p.id===id).name} added to your demo bag`)}
function renderProducts(category='All'){const list=products.filter(p=>category==='All'||p.category===category);document.querySelector('#products').innerHTML=list.map(p=>`<article class="product-card"><div class="product-visual"><button class="product-open" data-detail="${p.id}" aria-label="View ${p.name}">${imageHTML(p)}</button><span class="product-index">WESTSIDE / ${String(products.indexOf(p)+1).padStart(2,'0')}</span><button class="product-add" data-add="${p.id}" aria-label="Add ${p.name} to demo bag">+</button></div><div class="product-meta"><div><h3><button data-detail="${p.id}" style="padding:0;text-align:left">${p.name}</button></h3><p>${p.category} / Silver tone</p></div><span class="price">${money(p.price)}</span></div></article>`).join('');document.querySelector('#results-count').textContent=`${list.length} PIECES`}
document.querySelector('.filters').addEventListener('click',e=>{const button=e.target.closest('[data-filter]');if(!button)return;for(const b of document.querySelectorAll('[data-filter]')){const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)}renderProducts(button.dataset.filter)});
const detail=document.querySelector('#product-dialog'),bagDialog=document.querySelector('#bag-dialog');let returnFocus;
function openDialog(dialog){returnFocus=document.activeElement;dialog.showModal()}
for(const dialog of [detail,bagDialog]){dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}})}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){close.closest('dialog').close();return}const add=e.target.closest('[data-add]');if(add){addToBag(add.dataset.add);return}const trigger=e.target.closest('[data-detail]');if(trigger){const p=products.find(p=>p.id===trigger.dataset.detail);document.querySelector('#detail-content').innerHTML=`<div class="detail-grid">${imageHTML(p)}<div class="detail-copy"><p class="eyebrow orange-text">${p.category.toUpperCase()} / CONCEPT PIECE</p><h2 id="detail-title">${p.name}</h2><p class="detail-price">${money(p.price)}</p><p>${p.description}</p><p>Illustrative design in a silver-tone finish. Image and price are samples, not a specification or offer for sale.</p><button class="button orange" data-add="${p.id}">ADD TO DEMO BAG <span>+</span></button></div></div>`;openDialog(detail)}});
function renderBag(){const chosen=products.filter(p=>bag[p.id]);document.querySelector('#bag-items').innerHTML=chosen.length?chosen.map(p=>`<div class="bag-row">${imageHTML(p)}<div><h3>${p.name}</h3><p>${money(p.price)} each</p><div class="quantity"><button data-quantity="${p.id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span aria-label="Quantity">${bag[p.id]}</span><button data-quantity="${p.id}" data-change="1" aria-label="Increase ${p.name} quantity" ${bag[p.id]>=99?'disabled':''}>+</button><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div></div></div>`).join(''):'<div class="empty">Your next signature is waiting.<br>Explore the collection to start your rotation.</div>';document.querySelector('#bag-total').textContent=money(chosen.reduce((sum,p)=>sum+p.price*bag[p.id],0))}
document.querySelector('#bag-open').addEventListener('click',()=>{renderBag();openDialog(bagDialog)});
bagDialog.addEventListener('click',e=>{const q=e.target.closest('[data-quantity]'),r=e.target.closest('[data-remove]');if(!q&&!r)return;if(q){const id=q.dataset.quantity;bag[id]=Math.min(99,bag[id]+Number(q.dataset.change));if(bag[id]<=0)delete bag[id]}else delete bag[r.dataset.remove];saveBag();renderBag();const next=q?[...bagDialog.querySelectorAll('[data-quantity]')].find(b=>b.dataset.quantity===q.dataset.quantity&&b.dataset.change===q.dataset.change&&!b.disabled):null;(next||bagDialog.querySelector('[data-close]')).focus()});
const menu=document.querySelector('#menu-toggle'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',!expanded);nav.classList.toggle('open',!expanded)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
renderProducts();saveBag();
